        assert_eq!(u["input_tokens"], 11);
        assert_eq!(u["output_tokens"], 22);
        assert_eq!(u["cache_creation_input_tokens"], 0); // defaulted
        assert_eq!(u["cache_read_input_tokens"], 0);
    }
