//! Anthropic Messages API provider (api.anthropic.com). Returns Anthropic's native
//! response JSON unchanged — it already carries `content` blocks (text + any
//! `tool_use`) and `usage`, which is exactly the normalized shape llm_complete returns.

use super::{post_json, usage_u64, LlmProvider, LlmRequest, Msg, ToolCall, Turn, TurnResult};

pub struct AnthropicProvider;

/// Map the normalized messages onto Anthropic's `messages` array. Assistant turns
/// carry `text` + `tool_use` blocks; tool results become `tool_result` blocks in a
/// user message. Consecutive `ToolResult`s are coalesced into ONE user message —
/// Anthropic requires strict user/assistant alternation and groups parallel tool
/// results together.
fn build_messages(msgs: &[Msg]) -> Vec<serde_json::Value> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < msgs.len() {
        match &msgs[i] {
            Msg::User(s) => {
                out.push(serde_json::json!({ "role": "user", "content": s }));
                i += 1;
            }
            Msg::Assistant { text, tool_calls } => {
                let mut content = Vec::new();
                if !text.is_empty() {
                    content.push(serde_json::json!({ "type": "text", "text": text }));
                }
                for tc in tool_calls {
                    content.push(serde_json::json!({
                        "type": "tool_use", "id": tc.id, "name": tc.name, "input": tc.args
                    }));
                }
                out.push(serde_json::json!({ "role": "assistant", "content": content }));
                i += 1;
            }
            Msg::ToolResult { .. } => {
                let mut blocks = Vec::new();
                while let Some(Msg::ToolResult { id, content }) = msgs.get(i) {
                    blocks.push(serde_json::json!({
                        "type": "tool_result", "tool_use_id": id, "content": content
                    }));
                    i += 1;
                }
                out.push(serde_json::json!({ "role": "user", "content": blocks }));
            }
        }
    }
    out
}

/// The `system` field with a prompt-cache breakpoint (#3458). Anthropic renders the request
/// prefix as `tools → system → messages`, so ONE `cache_control` on the (last) system block caches
/// BOTH the tool definitions and the system prompt — the largest stable prefix, byte-identical every
/// turn of a session. An EMPTY prompt gets the bare string (no block; nothing to cache); a prompt
/// below the model's minimum cacheable prefix (2048 tokens on `claude-sonnet-4-6`, 4096 on Opus)
/// silently won't cache, which is a no-op, not an error. Caching is GA — no beta header. The
/// response's `usage.cache_creation_input_tokens` / `cache_read_input_tokens` report the split
/// (`normalize_usage` already surfaces them).
fn cached_system(system: &str) -> serde_json::Value {
    if system.is_empty() {
        return serde_json::Value::String(String::new());
    }
    serde_json::json!([
        { "type": "text", "text": system, "cache_control": { "type": "ephemeral" } }
    ])
}

/// Build the Anthropic `/v1/messages` request body for a tool-using turn.
/// Pure — unit-testable without I/O.
pub(crate) fn turn_request_body(t: &Turn) -> serde_json::Value {
    let tools: Vec<serde_json::Value> = t
        .tools
        .iter()
        .map(|d| serde_json::json!({ "name": d.name, "description": d.description, "input_schema": d.schema }))
        .collect();
    serde_json::json!({
        "model": t.model,
        "max_tokens": t.max_tokens,
        "system": cached_system(&t.system),
        "messages": build_messages(&t.messages),
        "tools": tools,
    })
}

/// Normalize Anthropic usage to the canonical 4-key shape `tokens.rs` parses
/// (`input_tokens`/`output_tokens`/`cache_creation_input_tokens`/`cache_read_input_tokens`);
/// Anthropic already uses these names, so this just defaults any missing key to 0.
pub(crate) fn normalize_usage(u: &serde_json::Value) -> serde_json::Value {
    serde_json::json!({
        "input_tokens": usage_u64(u, "input_tokens"),
        "output_tokens": usage_u64(u, "output_tokens"),
        "cache_creation_input_tokens": usage_u64(u, "cache_creation_input_tokens"),
        "cache_read_input_tokens": usage_u64(u, "cache_read_input_tokens"),
    })
}

/// Parse an Anthropic response into a [`TurnResult`]: text from `text` blocks,
/// tool calls from `tool_use` blocks. Pure — unit-testable without I/O.
pub(crate) fn parse_turn_response(raw: &serde_json::Value) -> TurnResult {
    let mut text = String::new();
    let mut tool_calls = Vec::new();
    if let Some(blocks) = raw["content"].as_array() {
        for b in blocks {
            match b["type"].as_str() {
                Some("text") => text.push_str(b["text"].as_str().unwrap_or("")),
                Some("tool_use") => tool_calls.push(ToolCall {
                    id: b["id"].as_str().unwrap_or("").to_string(),
                    name: b["name"].as_str().unwrap_or("").to_string(),
                    args: b["input"].clone(),
                }),
                _ => {}
            }
        }
    }
    TurnResult {
        text,
        tool_calls,
        usage: normalize_usage(raw.get("usage").unwrap_or(&serde_json::Value::Null)),
        stop_reason: raw["stop_reason"].as_str().unwrap_or("").to_string(),
    }
}

/// Build the Anthropic `/v1/messages` request body (top-level `system`, native
/// `messages` + `tools`). Pure — extracted so it can be unit-tested without I/O.
pub(super) fn build_request_body(req: &LlmRequest) -> serde_json::Value {
    serde_json::json!({
        "model": req.model,
        "max_tokens": req.max_tokens,
        "system": cached_system(&req.system),
        "messages": req.messages,
        "tools": req.tools,
    })
}

/// Base URL for the Anthropic Messages API. Production passes this; tests point the
/// `*_at` helpers at a localhost mock so the real send path is exercised offline.
pub(crate) const ANTHROPIC_BASE_URL: &str = "https://api.anthropic.com";

/// The Anthropic auth/version headers (identical for `complete` and `turn`).
fn auth_headers(api_key: &str) -> Vec<(&'static str, String)> {
    vec![
        ("x-api-key", api_key.to_string()),
        ("anthropic-version", "2023-06-01".to_string()),
    ]
}

impl AnthropicProvider {
    /// `complete` against an arbitrary base URL (production passes [`ANTHROPIC_BASE_URL`];
    /// tests point it at a localhost mock). Threading the base-url here lets the real
    /// send path (`post_json` + status/error handling) be exercised end-to-end without
    /// the network — the trait method below just supplies the production host.
    pub(crate) async fn complete_at(
        &self,
        base_url: &str,
        req: &LlmRequest,
        api_key: &str,
    ) -> Result<serde_json::Value, String> {
        post_json(
            &format!("{base_url}/v1/messages"),
            &auth_headers(api_key),
            &build_request_body(req),
        )
        .await
    }

    /// `turn` against an arbitrary base URL (see [`Self::complete_at`]).
    pub(crate) async fn turn_at(
        &self,
        base_url: &str,
        t: &Turn,
        api_key: &str,
    ) -> Result<TurnResult, String> {
        let json = post_json(
            &format!("{base_url}/v1/messages"),
            &auth_headers(api_key),
            &turn_request_body(t),
        )
        .await?;
        Ok(parse_turn_response(&json))
    }
}

impl LlmProvider for AnthropicProvider {
    async fn complete(&self, req: &LlmRequest, api_key: &str) -> Result<serde_json::Value, String> {
        self.complete_at(ANTHROPIC_BASE_URL, req, api_key).await
    }

    async fn turn(&self, t: &Turn, api_key: &str) -> Result<TurnResult, String> {
        self.turn_at(ANTHROPIC_BASE_URL, t, api_key).await
    }
}

